const zone = 'Europe/Rome';
const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', { timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
const value = type => parts.find(p => p.type === type).value;
const todayAtRomeMidnight = new Date(Date.UTC(+value('year'), +value('month') - 1, +value('day')));
todayAtRomeMidnight.setUTCDate(todayAtRomeMidnight.getUTCDate() - 1);
const target_date = todayAtRomeMidnight.toISOString().slice(0, 10);
const display_date = target_date.slice(8, 10) + '.' + target_date.slice(5, 7) + '.' + target_date.slice(0, 4);
return [{ json: { target_date, display_date, timezone: zone, max_pages: 16, stations: [
  { slug: 'rds-relax', station: 'RDS Relax' },
  { slug: 'radio-monte-carlo', station: 'Radio Monte Carlo' },
  { slug: 'dimensione-suono-soft', station: 'Dimensione Suono Soft' }
] } }];

const input = $input.first().json;
const raw = input.body ?? input.data ?? input;
const payload = typeof raw === 'string' ? (() => { try { return JSON.parse(raw); } catch { return { html: raw }; } })() : raw;
const html = String(payload.html ?? payload.body ?? '');
const decode = value => String(value || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#39;|&apos;/gi, "'").replace(/&quot;/gi, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/\s+/g, ' ').trim();
const norm = value => decode(value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const starts = [...html.matchAll(/<span[^>]*itemprop=["']startDate["'][^>]*content=["']([^"']+)["'][^>]*>/gi)];
const parsed = [];
for (let i = 0; i < starts.length; i++) {
  const date = starts[i][1];
  const from = starts[i].index;
  const block = html.slice(from, starts[i + 1]?.index ?? html.length);
  const artist = block.match(/itemprop=["']byArtist["'][^>]*>([\s\S]*?)<\/span>/i)?.[1];
  const title = block.match(/itemprop=["']name["'][^>]*>([\s\S]*?)<\/span>/i)?.[1];
  if (!artist || !title || !/^\d{4}-\d{2}-\d{2}T/.test(date) || date.slice(0, 10) !== input.target_date) continue;
  const a = decode(artist), t = decode(title);
  if (!a || !t) continue;
  parsed.push({ station: input.station, played_at: date, artist: a, title: t, normalized_artist: norm(a), normalized_title: norm(t) });
}
const ids = [...html.matchAll(/\bdata-id=["']([^"']+)["']/gi)].map(m => m[1]);
const all = [...(Array.isArray(input.accumulatedTracks) ? input.accumulatedTracks : []), ...parsed];
const seen = new Map(); for (const t of all) seen.set([t.station, t.played_at, t.normalized_artist, t.normalized_title].join('|'), t);
const last_id = ids.at(-1) || input.last_id || '';
const has_more = Boolean(last_id && last_id !== input.last_id && /js-morePageBtn/.test(html) && input.page < input.max_pages && parsed.length > 0);
return [{ json: { ...input, page: input.page + 1, last_id, accumulatedTracks: [...seen.values()], page_tracks: parsed.length, has_more, http_status: input.statusCode ?? null } }];

const tracks = Array.isArray($json.accumulatedTracks) ? $json.accumulatedTracks : [];
if (!tracks.length) return [{ json: { station: '__skip__', played_at: '2000-01-01T00:00:00+00:00', artist: '', title: '', normalized_artist: '', normalized_title: '' } }];
return tracks.map((track, index) => ({ json: track, pairedItem: { item: 0 } }));

