const tracks = $input.all().map(i => i.json);
if (!tracks.length) return [{ json: { has_data: false, formatted_text: 'Nessun passaggio disponibile negli ultimi 7 giorni: report non generato.' } }];
const instruction = 'Sei AC Music Intelligence. Analizza esclusivamente i dati forniti. Deezer rank e deezer_popularity sono metriche Deezer, non Spotify. Restituisci SOLO JSON valido con summary, grandi_assenti, da_incrementare, da_far_uscire, radar. Ogni lista deve essere un array. Non inventare valori o brani.';
return [{ json: { has_data: true, groq_body: { model: 'llama-3.3-70b-versatile', response_format: { type: 'json_object' }, temperature: 0.2, messages: [{ role: 'system', content: instruction }, { role: 'user', content: JSON.stringify({ timeframe_days: 7, tracks }) }] } } }];

const tracks = $input.all().map(item => item.json);

if (!tracks || tracks.length === 0) {
  return [{ json: { formatted_text: "📋 *REPORT STRATEGICO WEEKLY: AC MUSIC INTELLIGENCE*\n\nNessun passaggio registrato negli ultimi 7 giorni." } }];
}

// Calculate dates
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(today.getDate() - 1);
const lastMonday = new Date(today);
lastMonday.setDate(today.getDate() - 7);

const formatDate = (d) => {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = d.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
};
const period = `dal ${formatDate(lastMonday)} al ${formatDate(yesterday)}`;

// Categorization
const grandi_assenti = [];
const da_incrementare = [];
const da_far_uscire = [];
const radar = [];

tracks.forEach(t => {
  const rdsSpins = parseInt(t.rds_relax_spins || 0);
  const rmcSpins = parseInt(t.rmc_spins || 0);
  const dsSoftSpins = parseInt(t.ds_soft_spins || 0);
  const pop = parseInt(t.deezer_popularity || 0);
  const inCatalog = Boolean(t.in_catalog);
  const cat = t.catalog_category || 'N/A';

  // 1. Grandi Assenti: NOT in catalog, spins on RDS Relax >= 2
  if (!inCatalog && rdsSpins >= 2) {
    grandi_assenti.push({
      artist: t.artist,
      title: t.title,
      rds_relax_spins: rdsSpins,
      pop: pop,
      reason: "Brano in alta rotazione su RDS Relax (benchmark), assente nel nostro palinsesto."
    });
  }

  // 2. Da Incrementare: IN catalog, category OLD/CLS/LOW, high spins on RDS Relax
  if (inCatalog && rdsSpins >= 3 && ['OLD', 'CLS', 'CAT', 'N/A'].includes(cat)) {
    da_incrementare.push({
      artist: t.artist,
      title: t.title,
      category: cat,
      rds_relax_spins: rdsSpins,
      reason: `Attualmente in categoria '${cat}'. Consigliato passaggio a rotazione HIT/REC.`
    });
  }

  // 3. Da Far Uscire: IN catalog (HIT/REC), 0 spins on RDS Relax
  if (inCatalog && rdsSpins === 0 && ['HIT', 'REC', 'HOT'].includes(cat)) {
    da_far_uscire.push({
      artist: t.artist,
      title: t.title,
      category: cat,
      pop: pop,
      reason: `Programmato come ${cat} ma assente su RDS Relax. Valutare riduzione o rimozione.`
    });
  }

  // 4. Radar: RMC or DS Soft spins >= 2, absent on RDS Relax
  if (rdsSpins === 0 && (rmcSpins >= 2 || dsSoftSpins >= 2)) {
    radar.push({
      artist: t.artist,
      title: t.title,
      rmc_spins: rmcSpins,
      ds_soft_spins: dsSoftSpins,
      pop: pop,
      reason: "In evidenza sulle emittenti radar AC (RMC / DS Soft)."
    });
  }
});

// Build Telegram Markdown Text
let text = `📋 *REPORT STRATEGICO WEEKLY: AC MUSIC INTELLIGENCE*\n`;
text += `*Periodo Analizzato:* ${period}\n`;
text += `*Totale Brani Analizzati:* ${tracks.length}\n\n`;

text += `🟢 *I GRANDI ASSENTI (${grandi_assenti.length})* - Da inserire in regia:\n`;
if (grandi_assenti.length === 0) {
  text += `_Nessun gap critico rilevato rispetto al benchmark._\n`;
} else {
  grandi_assenti.slice(0, 10).forEach(t => {
    text += `- *${t.artist}* - _${t.title}_ (RDS Relax: ${t.rds_relax_spins} passaggi, Pop: ${t.pop}/100)\n  _Consiglio: ${t.reason}_\n`;
  });
}

text += `\n🟡 *DA INCREMENTARE (${da_incrementare.length})* - Aumentare rotazioni:\n`;
if (da_incrementare.length === 0) {
  text += `_Le rotazioni dei brani in catalogo sono allineate._\n`;
} else {
  da_incrementare.slice(0, 10).forEach(t => {
    text += `- *${t.artist}* - _${t.title}_ (Cat: ${t.category}, RDS Relax: ${t.rds_relax_spins})\n  _Consiglio: ${t.reason}_\n`;
  });
}

text += `\n🔴 *DA FAR USCIRE (${da_far_uscire.length})* - Rami secchi da eliminare:\n`;
if (da_far_uscire.length === 0) {
  text += `_Nessun brano fuori target in alta rotazione._\n`;
} else {
  da_far_uscire.slice(0, 10).forEach(t => {
    text += `- *${t.artist}* - _${t.title}_ (Cat: ${t.category}, Pop: ${t.pop}/100)\n  _Consiglio: ${t.reason}_\n`;
  });
}

text += `\n🕵️ *IL RADAR COMPETITOR (${radar.length})* - Consigliati da RMC / DS Soft:\n`;
if (radar.length === 0) {
  text += `_Nessun brano radar emergente rilevato._\n`;
} else {
  radar.slice(0, 10).forEach(t => {
    text += `- *${t.artist}* - _${t.title}_ (RMC: ${t.rmc_spins}, DS Soft: ${t.ds_soft_spins})\n  _Consiglio: ${t.reason}_\n`;
  });
}

return [{ json: { formatted_text: text } }];

const item = $input.first(); if (!item.binary) return [{ json: { status: 'error', message: 'Nessun CSV caricato.' } }];
const key = Object.keys(item.binary)[0]; const text = Buffer.from(item.binary[key].data, 'base64').toString('utf8').replace(/^\uFEFF/, '');
const delimiter = (text.match(/;/g)?.length || 0) >= (text.match(/,/g)?.length || 0) ? ';' : ',';
const rows = []; let row = [], field = '', quote = false;
for (let i = 0; i < text.length; i++) { const c = text[i], n = text[i + 1]; if (c === '"' && quote && n === '"') { field += '"'; i++; } else if (c === '"') quote = !quote; else if (c === delimiter && !quote) { row.push(field.trim()); field = ''; } else if ((c === '\n' || c === '\r') && !quote) { if (c === '\r' && n === '\n') i++; row.push(field.trim()); if (row.some(Boolean)) rows.push(row); row = []; field = ''; } else field += c; }
if (field || row.length) { row.push(field.trim()); rows.push(row); }
if (rows.length < 2) return [{ json: { status: 'error', message: 'CSV vuoto o senza intestazione.' } }];
const header = rows.shift().map(x => x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_'));
const col = (...names) => { const i = header.findIndex(h => names.includes(h)); return i >= 0 ? i : -1; };
const artistCol = col('artist','artista','interprete'), titleCol = col('title','titolo','brano'), categoryCol = col('category','categoria'), spinsCol = col('spins_total','passaggi_totali','spins');
if (artistCol < 0 || titleCol < 0) return [{ json: { status: 'error', message: 'Intestazioni CSV mancanti: artista/artist e titolo/title.' } }];
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
return rows.filter(r => r[artistCol] && r[titleCol]).map((r, index) => ({ json: { artist: r[artistCol], title: r[titleCol], normalized_artist: norm(r[artistCol]), normalized_title: norm(r[titleCol]), category: categoryCol >= 0 ? r[categoryCol] : '', spins_total: Math.max(0, parseInt((spinsCol >= 0 ? r[spinsCol] : '0').replace(/[^0-9-]/g, ''), 10) || 0), status: 'ok' }, pairedItem: { item: index } }));

